BEGIN
    DECLARE v_i INT DEFAULT 1;
    DECLARE v_j INT DEFAULT 1;
    DECLARE v_pedidos_qtd INT;
    DECLARE v_itens_qtd INT;
    DECLARE v_cliente_id INT;
    DECLARE v_pedido_id INT;
    DECLARE v_produto_id INT;
    DECLARE v_preco_prod DECIMAL(12,3);
    DECLARE v_qtde_item INT;
    DECLARE v_total_pedido DECIMAL(12,3);
    DECLARE v_random_logradouro INT;
    DECLARE v_localidade INT;
    DECLARE v_data_pedido DATETIME;
    DECLARE v_status INT;

    -- Adicionados comandos para limpar tabelas antes de nova carga
    SET FOREIGN_KEY_CHECKS = 0;
    TRUNCATE TB_ITEM_PEDIDO;
    TRUNCATE TB_PEDIDO;
    TRUNCATE TB_SITUACAO_PEDIDO;
    TRUNCATE TB_PRODUTO;
    TRUNCATE TB_CATEGORIA_PRODUTO;
    TRUNCATE TB_CONTATO_CLIENTE;
    TRUNCATE TB_TIPO_CONTATO_CLIENTE;
    TRUNCATE TB_CLIENTE;
    TRUNCATE TB_LOGRADOURO;
    TRUNCATE TB_LOCALIDADE;
    TRUNCATE TB_CIDADE;
    TRUNCATE TB_ESTADO;
    SET FOREIGN_KEY_CHECKS = 1;

    -- 1. CARGA DE ESTADOS
    INSERT INTO TB_ESTADO (SG_UF, NM_ESTADO) VALUES
    ('AC','Acre'),('AL','Alagoas'),('AP','Amapá'),('AM','Amazonas'),('BA','Bahia'),('CE','Ceará'),
    ('DF','Distrito Federal'),('ES','Espírito Santo'),('GO','Goiás'),('MA','Maranhão'),('MT','Mato Grosso'),
    ('MS','Mato Grosso do Sul'),('MG','Minas Gerais'),('PA','Pará'),('PB','Paraíba'),('PR','Paraná'),
    ('PE','Pernambuco'),('PI','Piauí'),('RJ','Rio de Janeiro'),('RN','Rio Grande do Norte'),
    ('RS','Rio Grande do Sul'),('RO','Rondônia'),('RR','Roraima'),('SC','Santa Catarina'),
    ('SP','São Paulo'),('SE','Sergipe'),('TO','Tocantins');

    -- 2. CARGA DE CIDADES
    INSERT INTO TB_CIDADE (NM_CIDADE, ID_ESTADO) VALUES
    ('Rio Branco',1),('Maceió',2),('Macapá',3),('Manaus',4),('Salvador',5),('Fortaleza',6),
    ('Brasília',7),('Vitória',8),('Aparecida de Goiânia',9),('Goiânia',9),('São Luís',10),
    ('Cuiabá',11),('Campo Grande',12),('Belo Horizonte',13),('Belém',14),('João Pessoa',15),
    ('Curitiba',16),('Recife',17),('Teresina',18),('Rio de Janeiro',19),('Natal',20),
    ('Porto Alegre',21),('Porto Velho',22),('Boa Vista',23),('Florianópolis',24),
    ('São Paulo',25),('Campinas',25),('Aracaju',26),('Palmas',27);

    -- 3. CARGA DE LOGRADOUROS (Simulação estruturada da base dos Correios)
    INSERT INTO TB_LOGRADOURO (CD_CEP, NM_LOGRADOURO, NM_BAIRRO, ID_CIDADE) VALUES
    ('74935250','Avenida Independência','Jardim Buriti Sereno',9),
    ('74948000','Rua das Flores','Bairro Independência',9),
    ('74000000','Avenida Anhanguera','Centro',10),
    ('20040002','Avenida Rio Branco','Centro',20),
    ('01001000','Praça da Sé','Sé',26),
    ('13012000','Avenida Francisco Glicério','Centro',27),
    ('30140010','Avenida Afonso Pena','Cruzeiro',14);

    -- 4. CARGA DE CATEGORIAS DE PRODUTOS (Sem o campo de especialização)
    INSERT INTO TB_CATEGORIA_PRODUTO (NM_CATEGORIA_PRODUTO) VALUES
    ('Alimentação'),
    ('Limpeza'),
    ('Vestuário'),
    ('Higiene Pessoal'),
    ('Eletro-Eletrônicos');

    -- 5. CARGA DE PRODUTOS DE SUPERMERCADO
    INSERT INTO TB_PRODUTO (NM_PRODUTO, VL_PRECO, ID_CATEGORIA_PRODUTO) VALUES
    ('Arroz Agulhinha 5kg', 24.990, 1),
    ('Feijão Carioca 1kg', 7.450, 1),
    ('Leite Integral 1L', 4.299, 1),
    ('Detergente Líquido 500ml', 2.150, 2),
    ('Desinfetante Lavanda 1L', 8.900, 2),
    ('Amaciante de Roupas 2L', 14.350, 2),
    ('Camiseta Básica Algodão', 39.900, 3),
    ('Meia Esportiva Par', 9.990, 3),
    ('Creme Dental Protetor', 3.490, 4),
    ('Shampoo Anticaspa 400ml', 18.750, 4),
    ('TV 65 polegadas LCD', 2500, 5),
    ('Microondas 32 litros', 300, 5);

    -- 5.1. CARGA DE TIPOS DE CONTATO DE CLIENTES (Ajuste Pós-IA)
    INSERT INTO TB_TIPO_CONTATO_CLIENTE (ID_TIPO_CONTATO, TX_TIPO_CONTATO) VALUES
    (1, 'E-Mail'), (2, 'Celular'), (3, 'Telefone Fixo');

    -- 5.2. CARGA DE SITUAÇÕES DE PEDIDOS (Ajuste Pós-IA)
    INSERT INTO TB_SITUACAO_PEDIDO (ID_SITUACAO, TX_SITUACAO_PEDIDO) VALUES
    (1, 'Em Processamento'), (2, 'Em Pagamento'), (3, 'Concluído'), (4, 'Cancelado');

    -- 6. LOOP PARA GERAR 1000 CLIENTES, CONTATOS E PEDIDOS (Linha do tempo: 2019 até o presente)
    SET v_i = 1;

    -- Tabela de Log de execução
    DROP TABLE IF EXISTS lg_execucao;
    CREATE TABLE lg_execucao (
        id_log INT AUTO_INCREMENT PRIMARY KEY,
        dt_log DATETIME,
        tx_mensagem VARCHAR(500)
    );

    WHILE v_i <= 1000 DO
        INSERT INTO lg_execucao
            VALUES (
                NULL,
                NOW(),
                CONCAT('Cliente: ', v_i, ' / ', 1000, ' (', (v_i / 1000) * 100, '%)')
        );

        SELECT ID_LOGRADOURO INTO v_random_logradouro FROM TB_LOGRADOURO ORDER BY RAND() LIMIT 1;
       
		INSERT INTO TB_LOCALIDADE (ID_LOGRADOURO, TX_NUMERO, TX_COMPLEMENTO)
        VALUES (
            v_random_logradouro,
            CONCAT(FLOOR(1 + RAND() * 2000)),
            IF(RAND() > 0.5, 'Casa', CONCAT('Apto ',FLOOR(100 + RAND() * 900)))
        );

		SET v_localidade = LAST_INSERT_ID();

        INSERT INTO TB_CLIENTE (NM_CLIENTE, CD_CPF, DT_NASCIMENTO, ID_LOCALIDADE)
        VALUES (
            CONCAT('Cliente Fictício ', v_i),
            LPAD(FLOOR(RAND() * 99999999999), 11, '0'),
            DATE_ADD('1970-01-01', INTERVAL FLOOR(RAND() * 12000) DAY),
            v_localidade
        );

        SET v_cliente_id = LAST_INSERT_ID();

        -- Contatos do cliente
        INSERT INTO TB_CONTATO_CLIENTE (ID_CLIENTE, ID_TIPO_CONTATO, TX_CONTATO, ST_WHATSAPP)
        VALUES (v_cliente_id, FLOOR(2 + (RAND() * 2)), CONCAT('629', LPAD(FLOOR(RAND() * 99999999), 8, '0')), IF(RAND() > 0.3, 'S', 'N'));
        
        INSERT INTO TB_CONTATO_CLIENTE (ID_CLIENTE, ID_TIPO_CONTATO, TX_CONTATO, ST_WHATSAPP)
        VALUES (v_cliente_id, 1, CONCAT('cliente', v_i, '@provedor.com'), 'N');

        -- Distribuição de pedidos por cliente
        SET v_pedidos_qtd = FLOOR(10 + RAND() * 50);
        SET v_j = 1;
        
        WHILE v_j <= v_pedidos_qtd DO
            -- Data retroativa simulada de 2019 até o limite atual
            SET v_data_pedido = DATE_ADD('2019-01-01 00:00:00', INTERVAL FLOOR(RAND() * 2690) DAY);
            SET v_data_pedido = DATE_ADD(v_data_pedido, INTERVAL FLOOR(RAND() * 86400) SECOND);
            
            SET v_status = FLOOR(1 + RAND() * 4);

            INSERT INTO TB_PEDIDO (ID_CLIENTE, DT_PEDIDO, VL_TOTAL, ID_SITUACAO_PEDIDO)
            VALUES (v_cliente_id, v_data_pedido, 0.000, v_status);
 
			SET v_pedido_id = LAST_INSERT_ID();

            -- Itens do pedido
            SET v_itens_qtd = FLOOR(1 + RAND() * 11);
            SET v_total_pedido = 0.000;
            
            BEGIN
                DECLARE v_k INT DEFAULT 1;
                WHILE v_k <= v_itens_qtd DO
                    SELECT ID_PRODUTO, VL_PRECO INTO v_produto_id, v_preco_prod FROM TB_PRODUTO ORDER BY RAND() LIMIT 1;
 
					SET v_qtde_item = FLOOR(1 + RAND() * 5);

                    INSERT IGNORE INTO TB_ITEM_PEDIDO (ID_PEDIDO, ID_PRODUTO, QT_PRODUTO, VL_UNITARIO)
                    VALUES (v_pedido_id, v_produto_id, v_qtde_item, v_preco_prod);
                    
                    IF ROW_COUNT() > 0 THEN
                        SET v_total_pedido = v_total_pedido + (v_qtde_item * v_preco_prod);
                    END IF;
                    
                    SET v_k = v_k + 1;
                END WHILE;
            END;

            -- Atualiza valor total final calculado do pedido
            UPDATE TB_PEDIDO SET VL_TOTAL = v_total_pedido WHERE ID_PEDIDO = v_pedido_id;

            SET v_j = v_j + 1;
        END WHILE;

        SET v_i = v_i + 1;
    END WHILE;
END ;;
